action.code:
for (const auto& neighbor : graph.get_neighbors(current_node)) {
    if (neighbor->visited) {
        continue;
    }

    double tentative_g_score = current_node->g + graph.get_edge_weight(current_node, neighbor);

    if (tentative_g_score < neighbor->g) {
        neighbor->parent = current_node;
        neighbor->g = tentative_g_score;
        neighbor->h = graph.calculate_heuristic(neighbor, end_node);
        neighbor->f = neighbor->g + neighbor->h;

        bool already_in_open = false;
        for (Node* node : open_list) {
            if (node == neighbor) {
                already_in_open = true;
                break;
            }
        }

        if (!already_in_open) {
            open_list.push_back(neighbor);
        }
    }
}
// END_CODE

